$('form').on('submit', function (event) {
	event.preventDefault();
	var userName=document.getElementById("userName").value;  
    var pwd=document.getElementById("pwd").value;
    if(userName=="李婷" &&  pwd=="1106"){
		$('form').fadeOut(500);
		$('.wrapper').addClass('form-success');
		requestFullScreen();
		setTimeout(function(){location.href="index1.html";},2000);
		//auto_link_html("index1.html");
	}
	else{
		alert("密码是你的生日哦!（密码为4位数）");
	}
});

function requestFullScreen() {
    var host = window.top;
    var root = host.document.documentElement;
    var mobile = host.matchMedia && host.matchMedia('(max-width: 960px)').matches;
    if (mobile) host.document.body.classList.add('entered');

    var request = root.requestFullscreen || root.webkitRequestFullscreen ||
                  root.mozRequestFullScreen || root.msRequestFullscreen;
    if (!request) return;

    try {
        var result = request.call(root);
        if (mobile && result && typeof result.then === 'function') {
            result.then(function () {
                var orientation = host.screen.orientation;
                if (orientation && orientation.lock) {
                    try {
                        var lock = orientation.lock('landscape');
                        if (lock && lock.catch) lock.catch(function () {});
                    } catch (error) {}
                }
            }).catch(function () {});
        }
    } catch (error) {}
}
function changeFrameHeight(){
    var ifm= document.getElementById("iframepage"); 
	if (!ifm) return;
    ifm.height=document.documentElement.clientHeight;

}

window.onresize=function(){  
     changeFrameHeight();  

}
